-- Additive address/zone records. No existing address, price or policy is rewritten.
CREATE TABLE "CustomerAddress" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"label" TEXT NOT NULL CHECK("label" IN ('HOME','WORK','OTHER')),"addressLine" TEXT NOT NULL,"landmark" TEXT NOT NULL DEFAULT '',"city" TEXT NOT NULL,"state" TEXT NOT NULL,"postalCode" VARCHAR(6) NOT NULL CHECK("postalCode" ~ '^[1-9][0-9]{5}$'),"instructions" TEXT NOT NULL DEFAULT '',"isDefault" BOOLEAN NOT NULL DEFAULT false,"version" INTEGER NOT NULL DEFAULT 0,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "CustomerAddress_customerId_archivedAt_idx" ON "CustomerAddress"("customerId","archivedAt");
CREATE UNIQUE INDEX "CustomerAddress_one_active_default" ON "CustomerAddress"("customerId") WHERE "isDefault"=true AND "archivedAt" IS NULL;
CREATE TABLE "DeliveryZone" ("id" TEXT PRIMARY KEY,"restaurantId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"name" TEXT NOT NULL,"postalCode" VARCHAR(6) NOT NULL CHECK("postalCode" ~ '^[1-9][0-9]{5}$'),"deliveryFee" DECIMAL(10,2) NOT NULL CHECK("deliveryFee">=0),"minimumOrder" DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK("minimumOrder">=0),"freeThreshold" DECIMAL(10,2) CHECK("freeThreshold">=0),"priority" INTEGER NOT NULL DEFAULT 0 CHECK("priority" BETWEEN -1000 AND 1000),"active" BOOLEAN NOT NULL DEFAULT true,"version" INTEGER NOT NULL DEFAULT 0,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DeliveryZone_restaurantId_postalCode_active_idx" ON "DeliveryZone"("restaurantId","postalCode","active");
-- Highest priority wins. Active ties are rejected rather than picking an arbitrary fee.
CREATE UNIQUE INDEX "DeliveryZone_active_priority_key" ON "DeliveryZone"("restaurantId","postalCode","priority") WHERE "active"=true AND "archivedAt" IS NULL;
ALTER TABLE "Order" ADD COLUMN "savedAddressId" TEXT REFERENCES "CustomerAddress"("id") ON DELETE SET NULL ON UPDATE CASCADE,ADD COLUMN "deliveryPostalCode" VARCHAR(6) CHECK("deliveryPostalCode" IS NULL OR "deliveryPostalCode" ~ '^[1-9][0-9]{5}$'),ADD COLUMN "deliveryAddressSnapshot" JSONB,ADD COLUMN "deliveryZoneId" TEXT REFERENCES "DeliveryZone"("id") ON DELETE RESTRICT ON UPDATE CASCADE,ADD COLUMN "deliveryZoneVersion" INTEGER,ADD COLUMN "legacyRequestHash" TEXT;
-- No guessed service areas are backfilled. New checkouts fail closed until an admin configures real rules.
